CREATE OR REPLACE PACKAGE BODY "BIGFUND"."PKG_2008802001_MGT" AS
  PROCEDURE proc_list(in_accnt_id IN varchar2, in_match_status IN varchar2, in_accnt_date1 IN varchar2, in_accnt_date2 IN varchar2, in_respond_date1 IN varchar2, in_respond_date2 IN varchar2, in_qrybeginpos IN varchar2, in_qrynum IN varchar2, out_flag OUT number, out_msg OUT varchar2, totalnum OUT varchar2, out_rel_cur OUT sys_refcursor) IS 
    v_proc_name db_log%.proc_name%;
    v_step_no db_log%.STEP_NO% := '';
  BEGIN
    out_flag := '0';
    out_msg := '托管服务报告列表';
    v_proc_name := 'pkg_clnt_rpt_info.proc_rpt_list';
    v_step_no := '2';
    v_step_no := '2.1';
    SELECT /*+ use_cplan */ COUNT(1) INTO totalnum
    FROM dat_clr_cash_dtl AS t, dat_trustee_acnt_detail AS d
    WHERE t.trade_code IN ('2008801001', '2008802001')
        AND t.account_id = in_accnt_id
        AND t.match_status = in_match_status
        AND t.account_date BETWEEN nvl (in_accnt_date1, '19000101') AND nvl (in_accnt_date2, '99991231')
        AND (t.respond_date BETWEEN nvl (in_respond_date1, '19000101') AND nvl (in_respond_date2, '99991231') OR t.respond_date IS NULL)
        AND t.interface_seq = d.interface_seq
        AND (t.operation_status = decode (t.trade_code, '2008801001', '0', t.operation_status) OR decode (t.trade_code, '2008801001', '0', t.operation_status) IS NULL);
    v_step_no := '2.2';
    OPEN out_rel_cur FOR SELECT /*+use_cplan*/s.account_id,
             s.accname,
             s.account_date,
             s.in_amount,
             s.describe,
             s.recipacc,
             s.recipnam,
             s.account_seqno,
             s.accnt_seqno,
             s.interface_seq,
             s.match_status,
             s.statusname,
             s.respond_date
        FROM (SELECT t.account_id,
                     (SELECT s.accname
                        FROM v_par_asset_acnt_info s
                       WHERE s.asset_acnt_id = t.account_id
                         AND rownum = 1) accname,
                     t.account_date,
                     t.in_amount,
                     t.describe,
                     d.recipacc,
                     d.recipnam,
                     t.account_seqno,
                     t.trade_code,
                     t.accnt_seqno,
                     t.match_status,
                     t.interface_seq,
                     decode(t.match_status, '0', '未匹配', '1', '已匹配') statusname,
                     t.respond_date,
                     row_number() over(ORDER BY t.account_date DESC, t.account_seqno, t.account_id, t.interface_seq,accno, d.serialno,
                     d.busidate, d.timestmp, d.updtranf, d.revtranf, d.trxcode, d.drcrf, d.amount, d.detailf, d.currtype, d.subcode, d.euoflag) rownm
                FROM dat_clr_cash_dtl t, dat_trustee_acnt_detail d
               WHERE t.trade_code IN ('2008801001', '2008802001')
                 AND t.account_id = in_accnt_id
                 AND t.match_status = in_match_status
                 AND t.account_date BETWEEN nvl(in_accnt_date1, '19000101') AND
                     nvl(in_accnt_date2, '99991231')
                 AND (t.respond_date BETWEEN
                     nvl(in_respond_date1, '19000101') AND
                     nvl(in_respond_date2, '99991231') OR
                     t.respond_date IS NULL)
                 AND t.interface_seq = d.interface_seq(+)
                 AND (t.operation_status =
                     decode(t.trade_code,
                             '2008801001',
                             '0',
                             t.operation_status) OR
                     decode(t.trade_code,
                             '2008801001',
                             '0',
                             t.operation_status) IS NULL)) s
         limit to_number(in_qrynum) offset to_number(in_qrybeginpos)-1;
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := '[ERRCODE:]' || "SQLCODE" || 'ERRMSG' || "SQLERRM";
      ROLLBACK;
      pack_log.log(v_proc_name, out_msg, v_step_no);
      COMMIT;
  END;
  PROCEDURE proc_main_ctl(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_amount IN varchar2, in_seq_no IN varchar2, in_interface_seq IN varchar2, in_oper_flag IN varchar2, in_respond_date IN varchar2, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2) IS 
    v_accnt_id_list pkg_param_common.arrytype := pkg_param_common.getarray(in_accnt_id, ',');
    v_accnt_date_list pkg_param_common.arrytype := pkg_param_common.getarray(in_accnt_date, ',');
    v_accnt_seqno_list pkg_param_common.arrytype := pkg_param_common.getarray(in_accnt_seqno, ',');
    v_amount_list pkg_param_common.arrytype := pkg_param_common.getarray(in_amount, ',');
    v_seq_no_list pkg_param_common.arrytype := pkg_param_common.getarray(in_seq_no, ',');
    v_interface_seq_list pkg_param_common.arrytype := pkg_param_common.getarray(in_interface_seq, ',');
  BEGIN
        FOR i IN 1..v_accnt_id_list.count LOOP

      BEGIN
        IF in_oper_flag = 1 THEN
          proc_match_account(v_accnt_id_list(i), v_accnt_date_list(i), v_accnt_seqno_list(i), v_amount_list(i), v_seq_no_list(i), v_interface_seq_list(i), in_user_id, out_flag, out_msg);
        ELSIF in_oper_flag = 2 THEN
          proc_modify(v_accnt_id_list(i), v_accnt_date_list(i), v_accnt_seqno_list(i), v_seq_no_list(i), v_interface_seq_list(i), v_amount_list(i), in_respond_date, in_user_id, out_flag, out_msg);
        ELSIF in_oper_flag = 3 THEN
          proc_cancel(v_accnt_id_list(i), v_accnt_date_list(i), v_accnt_seqno_list(i), v_seq_no_list(i), v_interface_seq_list(i), v_amount_list(i), in_user_id, out_flag, out_msg);
        END IF;
      END;
    END LOOP;
  END;
  PROCEDURE proc_match(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_seq_no IN number, in_interface_seq IN number, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2, out_date OUT varchar2) IS 
    v_respond_date dat_clr_cash_dtl%.respond_date%;
    v_flag prm_sth_payback_accnt_date%.accnt_flag%;
    v_trade_code dat_clr_cash_dtl%.trade_code%;
    v_amout dat_clr_cash_dtl%.in_amount%;
  BEGIN
    out_flag := '0';
    out_msg := '匹配成功';
    proc_get_respond_date(in_accnt_id, in_accnt_date, in_seq_no, in_interface_seq, out_flag, out_msg, v_respond_date);

    BEGIN
      SELECT t.trade_code, t.in_amount INTO v_trade_code, v_amout
      FROM dat_clr_cash_dtl AS t
      WHERE t.account_date = in_accnt_date
          AND t.account_seqno = in_seq_no
          AND t.account_id = in_accnt_id
          AND t.interface_seq = in_interface_seq;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
    UPDATE dat_clr_cash_dtl AS t SET t.match_status = '1', t.trade_code = '2008802001', t.respond_date = v_respond_date
    WHERE t.account_date = in_accnt_date
        AND t.account_seqno = in_seq_no
        AND t.account_id = in_accnt_id
        AND t.interface_seq = in_interface_seq;
    COMMIT;

    BEGIN
      SELECT t.accnt_flag INTO v_flag
      FROM prm_sth_payback_accnt_date AS t
      WHERE t.accnt_id = in_accnt_id;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
    IF v_flag = '2' THEN
      out_date := v_respond_date;
    ELSE
      out_date := in_accnt_date;
    END IF;
    proc_sth_accnt_log(out_date, in_accnt_id, v_trade_code, '2008802001', v_amout, in_user_id);
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := 'errcode: ' || "SQLCODE" || ' errmsg: ' || "SQLERRM";
      ROLLBACK;
  END;
  PROCEDURE proc_match_account(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_amount IN number, in_seq_no IN number, in_interface_seq IN number, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2) IS 
    v_date dat_clr_cash_dtl%.respond_date%;
    outer_msg varchar2(30) := '2';
    another_outer_msg varchar2(30) := '2';
  BEGIN
    proc_match(in_accnt_id, in_accnt_date, in_seq_no, in_interface_seq, in_user_id, out_flag, another_outer_msg, v_date);
    IF v_date IS NOT NULL THEN
            WHILE v_date IS NOT NULL LOOP
        proc_match(in_accnt_id, in_accnt_date, in_seq_no, in_interface_seq, in_user_id, out_flag, outer_msg, v_date);
      END LOOP;
      pkg_sth_accnt.proc_sth_set_accnt_info(v_date, in_accnt_id, '2008802001', in_seq_no, in_amount, '0', in_accnt_seqno);
    END IF;
    out_flag := '0';
    out_msg := '匹配成功';
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := 'errcode: ' || "SQLCODE" || ' errmsg: ' || "SQLERRM";
      ROLLBACK;
  END;
  PROCEDURE proc_modify(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_seq_no IN number, in_interface_seq IN number, in_amount IN number, in_respond_date IN varchar2, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2) IS 
    v_date varchar2(8);
    v_trade_code dat_clr_cash_dtl%.trade_code%;
  BEGIN
    out_flag := '0';
    out_msg := '修改成功';

    BEGIN
      SELECT t.trade_code INTO v_trade_code
      FROM dat_clr_cash_dtl AS t
      WHERE t.account_date = in_accnt_date
          AND t.account_seqno = in_seq_no
          AND t.account_id = in_accnt_id
          AND t.interface_seq = in_interface_seq;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
    UPDATE dat_clr_cash_dtl AS t SET t.match_status = '1', t.trade_code = '2008802001', t.respond_date = in_respond_date
    WHERE t.account_date = in_accnt_date
        AND t.account_seqno = in_seq_no
        AND t.account_id = in_accnt_id
        AND t.interface_seq = in_interface_seq;
    COMMIT;

    BEGIN
      SELECT decode(t.accnt_flag, '1', in_accnt_date, in_respond_date) INTO v_date
      FROM prm_sth_payback_accnt_date AS t
      WHERE t.accnt_id = in_accnt_id;
    EXCEPTION
      WHEN OTHERS THEN
        v_date := in_accnt_date;
    END;
    proc_sth_accnt_log(v_date, in_accnt_id, v_trade_code, '2008802001', in_amount, in_user_id);
    pkg_sth_accnt.proc_sth_set_accnt_info(v_date, in_accnt_id, '2008802001', in_seq_no, in_amount, '0', in_accnt_seqno);
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := 'errcode: ' || "SQLCODE" || ' errmsg: ' || "SQLERRM";
      ROLLBACK;
  END;
  PROCEDURE proc_cancel(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_seq_no IN number, in_interface_seq IN number, in_amount IN number, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2) IS 
    v_trade_code dat_clr_cash_dtl%.trade_code%;
    v_amout dat_clr_cash_dtl%.in_amount%;
  BEGIN
    out_flag := '0';
    out_msg := '解除匹配成功';

    BEGIN
      SELECT t.trade_code, t.in_amount INTO v_trade_code, v_amout
      FROM dat_clr_cash_dtl AS t
      WHERE t.account_date = in_accnt_date
          AND t.account_seqno = in_seq_no
          AND t.account_id = in_accnt_id
          AND t.interface_seq = in_interface_seq;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
    UPDATE dat_clr_cash_dtl AS t SET t.match_status = '0', t.respond_date = '', t.trade_code = '2008801001', t.operation_status = '0'
    WHERE t.account_date = in_accnt_date
        AND t.account_seqno = in_seq_no
        AND t.account_id = in_accnt_id
        AND t.interface_seq = in_interface_seq;
    COMMIT;
    proc_sth_accnt_log(in_accnt_date, in_accnt_id, v_trade_code, '2008801001', v_amout, in_user_id);
    pkg_sth_accnt.proc_sth_set_accnt_info(in_accnt_date, in_accnt_id, '2008801001', in_seq_no, in_amount, '0', in_accnt_seqno);
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := 'errcode: ' || "SQLCODE" || ' errmsg: ' || "SQLERRM";
      ROLLBACK;
  END;
  PROCEDURE proc_get_date(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_seq_no IN varchar2, in_interface_seq IN number, out_flag OUT number, out_msg OUT varchar2, out_date OUT varchar2) IS 
    v_flag prm_sth_payback_accnt_date%.accnt_flag%;
  BEGIN
    out_flag := '0';
    out_msg := '获取入账日期成功';

    BEGIN
      SELECT t.accnt_flag INTO v_flag
      FROM prm_sth_payback_accnt_date AS t
      WHERE t.accnt_id = in_accnt_id;
    EXCEPTION
      WHEN OTHERS THEN
        v_flag := '1';
    END;
    IF v_flag = '1' THEN
      out_date := in_accnt_date;
      RETURN;
    ELSE
      proc_get_respond_date(in_accnt_id, in_accnt_date, in_seq_no, in_interface_seq, out_flag, out_msg, out_date);
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := 'errcode: ' || "SQLCODE" || ' errmsg: ' || "SQLERRM";
      out_date := to_char(now(), 'yyyymmdd');
  END;
  PROCEDURE proc_get_respond_date(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_seq_no IN varchar2, in_interface_seq IN number, out_flag OUT number, out_msg OUT varchar2, out_date OUT varchar2) IS 
  BEGIN
    out_flag := '0';
    out_msg := '获取入账日期成功';

    BEGIN
      SELECT MAX(SUBSTRING(t.send_tm FROM 0 FOR 8)) INTO out_date
      FROM dat_zl_batchpayment AS t, par_sys_plan AS b, dat_clr_cash_dtl AS s, dat_trustee_acnt_detail AS c
      WHERE s.account_id = in_accnt_id
          AND s.account_date = in_accnt_date
          AND s.account_seqno = in_seq_no
          AND s.interface_seq = in_interface_seq
          AND t.planid = b.plan_id
          AND b.acnt_id = s.account_id
          AND s.interface_seq = c.interface_seq
          AND t.beneaccount = c.recipacc
          AND t.apaysum = s.in_amount
          AND s.account_date BETWEEN t.apaydate AND SUBSTRING (t.send_tm FROM 1 FOR 8);
    EXCEPTION
      WHEN OTHERS THEN
        out_date := '';
    END;
    IF out_date IS NULL THEN

      BEGIN
        SELECT MAX(to_char(t.pay_tm, 'yyyymmdd')) INTO out_date
        FROM tmp_batchpay_submit AS t, dat_clr_cash_dtl AS s, dat_trustee_acnt_detail AS b, par_sys_plan AS p
        WHERE s.account_id = in_accnt_id
            AND s.account_date = in_accnt_date
            AND s.account_seqno = in_seq_no
            AND s.interface_seq = in_interface_seq
            AND s.interface_seq = b.interface_seq
            AND t.rece_account = b.recipacc
            AND t.status = '26'
            AND s.account_date BETWEEN t.inst_date AND to_char (t.pay_tm, 'yyyymmdd')
            AND t.pay_amount / 100 = s.in_amount
            AND s.account_id = p.acnt_id
            AND p.plan_id = t.planid
            AND s.out_amount = 0;
      EXCEPTION
        WHEN no_data_found THEN
          out_date := to_char(now(), 'yyyymmdd');
      END;
    END IF;
    IF out_date IS NULL THEN
      out_date := to_char(now(), 'yyyymmdd');
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      out_flag := '1';
      out_msg := 'errcode: ' || "SQLCODE" || ' errmsg: ' || "SQLERRM";
      out_date := to_char(now(), 'yyyymmdd');
  END;
END;

CREATE OR REPLACE PACKAGE "BIGFUND"."PKG_2008802001_MGT" AS
  TYPE refcur IS REF CURSOR;
  PROCEDURE proc_list(in_accnt_id IN varchar2, in_match_status IN varchar2, in_accnt_date1 IN varchar2, in_accnt_date2 IN varchar2, in_respond_date1 IN varchar2, in_respond_date2 IN varchar2, in_qrybeginpos IN varchar2, in_qrynum IN varchar2, out_flag OUT number, out_msg OUT varchar2, totalnum OUT varchar2, out_rel_cur OUT sys_refcursor);
  PROCEDURE proc_main_ctl(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_amount IN varchar2, in_seq_no IN varchar2, in_interface_seq IN varchar2, in_oper_flag IN varchar2, in_respond_date IN varchar2, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2);
  PROCEDURE proc_match(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_seq_no IN number, in_interface_seq IN number, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2, out_date OUT varchar2);
  PROCEDURE proc_match_account(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_amount IN number, in_seq_no IN number, in_interface_seq IN number, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2);
  PROCEDURE proc_modify(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_seq_no IN number, in_interface_seq IN number, in_amount IN number, in_respond_date IN varchar2, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2);
  PROCEDURE proc_cancel(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_accnt_seqno IN varchar2, in_seq_no IN number, in_interface_seq IN number, in_amount IN number, in_user_id IN varchar2, out_flag OUT number, out_msg OUT varchar2);
  PROCEDURE proc_get_date(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_seq_no IN varchar2, in_interface_seq IN number, out_flag OUT number, out_msg OUT varchar2, out_date OUT varchar2);
  PROCEDURE proc_get_respond_date(in_accnt_id IN varchar2, in_accnt_date IN varchar2, in_seq_no IN varchar2, in_interface_seq IN number, out_flag OUT number, out_msg OUT varchar2, out_date OUT varchar2);
END;
